#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
PAYLOAD = {'fia_core': '# SPDX-License-Identifier: Apache-2.0\n# SPDX-FileCopyrightText: Copyright contributors to the vLLM project\n"""Opt-in K3 full576 FP8 cache. No persistent BF16 history or Q-by-K indices.\n\nKV uses unscaled FP8, matching the pinned CANN K3 recipe\'s unit descale.\nCaller-owned cache pages and their padding/offset are preserved. Metadata is\nshared across layers in an attention group; only captured capacities are kept.\n"""\n\nimport importlib\nimport math\nfrom dataclasses import dataclass\n\nimport torch\nimport torch_npu\n\nQFM_WIDTH = 576\nQFM_VALUE = 512\nQFM_BLOCK = 128\nQFM_TILE = 32\nQFM_MAX_Q = 16\nQFM_MASK = 2048\nQFM_FP8_MAX = 448.0\n# cann-recipes-infer 4447f2f0972cb9287e069e3994b1d46ffe244ebc:\n# KimiMLAAttention.prepare_prolog_weights registers mla_kv_scale=[1.0].\n# This is an identity conversion, not a calibrated model accuracy guarantee.\nQFM_KV_DESCALE = 1.0\nQFM_HEADS = (1, 2, 4, 6, 8, 12, 16, 24, 32, 48, 64, 96, 128)\n\n\ndef select_qfm(impl, config) -> bool:\n    """Do not turn on the draft model or unrelated attention layers."""\n    if not config.enable_kimi_k3_qfm_c8 or impl.is_draft_model:\n        return False\n    # MRV2 DSpark retains the target model_config while constructing its\n    # draft. Kimi also sets draft RoPE only AFTER the MLA impl is created.\n    # Neither runner_type nor use_mla_rope identifies that construction\n    # reliably. Read the loader\'s live tag (never import its value by copy)\n    # before validating/choosing a target-only QFM cache layout.\n    if importlib.import_module("vllm.compilation.backends").model_tag == "dspark_head":\n        return False\n    if config.enable_sparse_sfa_c8:\n        raise ValueError("Disable enable_sparse_sfa_c8: packed656 and full576 QFM are different cache formats")\n    vcfg = impl.vllm_config\n    if impl.use_mla_rope or impl.kv_lora_rank != QFM_VALUE or impl.qk_rope_head_dim != 64:\n        raise ValueError("K3 QFM requires No-RoPE MLA latent512 + raw64")\n    if not vcfg.use_v2_model_runner or not impl.support_fp8_attention:\n        raise ValueError("K3 QFM requires A5 and ModelRunner V2")\n    if impl.num_kv_heads != 1 or impl.num_heads not in QFM_HEADS:\n        raise ValueError(f"QFM unsupported local query/KV heads: {impl.num_heads}/{impl.num_kv_heads}")\n    kernel_pages_per_manager(vcfg.cache_config.block_size)\n    if vcfg.cache_config.cache_dtype != "auto" or impl.fa_quant_layer:\n        raise ValueError("QFM owns full576 FP8 storage: use --kv-cache-dtype auto and no legacy FA quant scheme")\n    if impl.enable_mlapo or impl.enable_kv_nz:\n        raise ValueError(\n            "QFM ordinary writer requires enable_mlapo=false and enable_kv_nz=false; fused writer not admitted"\n        )\n    if impl.pcp_enabled or impl.is_pcp_decode_sharded:\n        raise ValueError("QFM PCP is not adapted in this candidate")\n    if vcfg.kv_transfer_config is not None or config.kvpp_config.size != 1:\n        raise ValueError("QFM KV transfer/KV layer parallelism is not adapted in this candidate")\n    if config.sparse_kv_offload_config.enabled:\n        raise ValueError("QFM does not use sparse KV offload")\n    if vcfg.speculative_config is not None and vcfg.speculative_config.method != "dspark":\n        raise ValueError("QFM speculative path is currently scoped to DSpark")\n    size = vcfg.parallel_config.decode_context_parallel_size\n    if impl.num_heads * size not in QFM_HEADS:\n        raise ValueError("QFM does not support this DCP-gathered query head count")\n    impl.qfm_fia_prefill = getattr(config, "enable_kimi_k3_qfm_fia_prefill", False)\n    return True\n\n\ndef kernel_pages_per_manager(manager_block_size):\n    """The KV manager owns large blocks; QFM consumes fixed 128-token pages."""\n    if (\n        isinstance(manager_block_size, bool)\n        or not isinstance(manager_block_size, int)\n        or manager_block_size <= 0\n        or manager_block_size % QFM_BLOCK\n    ):\n        raise ValueError(\n            f"QFM requires --block-size to be a positive multiple of {QFM_BLOCK}; "\n            f"resolved manager block size is {manager_block_size}"\n        )\n    return manager_block_size // QFM_BLOCK\n\n\ndef align_qfm_page_bytes(page_bytes, manager_block_sizes):\n    """Align the shared physical page before cache budgeting/allocation."""\n    alignment = math.lcm(*(kernel_pages_per_manager(size) * QFM_TILE for size in manager_block_sizes))\n    return (page_bytes + alignment - 1) // alignment * alignment\n\n\ndef cache_view_for_manager(raw, manager_block_size, page_bytes, kernel_block_size=QFM_BLOCK):\n    """Split final allocator pages into uniformly strided QFM kernel pages.\n\n    MRV2 BlockTables already expands manager ID b to b*ratio+[0..ratio-1]\n    and computes slots with kernel size 128. Do not expand either again in\n    QFM metadata. Page padding is distributed between the kernel views, so\n    ratio*kernel_stride is exactly the allocator\'s physical manager stride.\n    """\n    ratio = kernel_pages_per_manager(manager_block_size)\n    if kernel_block_size != QFM_BLOCK:\n        raise ValueError(f"QFM needs kernel block size {QFM_BLOCK}, got {kernel_block_size}")\n    if page_bytes < manager_block_size * QFM_WIDTH or page_bytes % (ratio * QFM_TILE):\n        raise ValueError(\n            f"QFM physical manager page {page_bytes} bytes must cover {manager_block_size * QFM_WIDTH} "\n            f"payload bytes and divide into {ratio} kernel pages with {QFM_TILE}-byte aligned strides"\n        )\n    if raw.numel() == 0 or raw.numel() % page_bytes:\n        raise ValueError("QFM raw buffer must contain whole physical manager pages")\n    return cache_view(raw, raw.numel() // page_bytes * ratio, page_bytes // ratio)\n\n\ndef cache_view(raw, blocks, page_bytes):\n    """One physical page per block, with offset inherited from the allocator."""\n    if raw.dtype not in (torch.uint8, torch.int8) or raw.ndim != 1:\n        raise ValueError("QFM allocator requires a single byte buffer")\n    if page_bytes < QFM_BLOCK * QFM_WIDTH or page_bytes % QFM_TILE:\n        raise ValueError("QFM physical page must hold full576 FP8 and align to 32 bytes")\n    needed = (blocks - 1) * page_bytes + QFM_BLOCK * QFM_WIDTH\n    if blocks <= 0 or needed > raw.numel() or raw.storage_offset() % QFM_TILE:\n        raise ValueError("QFM cache allocation is too small or unaligned")\n    return torch.as_strided(\n        raw.view(torch.float8_e4m3fn),\n        (blocks, 1, QFM_WIDTH // QFM_TILE, QFM_BLOCK, QFM_TILE),\n        (page_bytes, QFM_BLOCK * QFM_WIDTH, QFM_BLOCK * QFM_TILE, QFM_TILE, 1),\n    )\n\n\ndef write_cache(rows, slots, cache, scale):\n    """Scatter 32-byte NZ tiles; native ScatterPaCache skips slot -1.\n\n    An offset-preserving contiguous alias avoids the old DSpark stride bug.\n    Invalid tokens do not alias a live token or depend on duplicate-write order.\n    """\n    if cache.dtype != torch.float8_e4m3fn or cache.shape[1:] != (1, 18, 128, 32):\n        raise ValueError("QFM requires full576 FP8 PA_NZ cache, not legacy packed656")\n    stride = cache.stride(0)\n    if cache.stride()[2:] != (4096, 32, 1) or stride % QFM_TILE:\n        raise ValueError("Invalid QFM PA_NZ strides")\n    span = (cache.shape[0] - 1) * stride + QFM_BLOCK * QFM_WIDTH\n    alias = torch.as_strided(cache, (span // QFM_TILE, 1, 1, QFM_TILE), (32, 32, 32, 1))\n    ids = slots.to(torch.int64)\n    tile = torch.arange(QFM_WIDTH // QFM_TILE, device=rows.device)\n    offsets = ids[:, None].div(QFM_BLOCK, rounding_mode="floor") * (stride // QFM_TILE)\n    offsets = offsets + tile[None, :] * QFM_BLOCK + ids[:, None].remainder(QFM_BLOCK)\n    offsets = torch.where(ids[:, None] >= 0, offsets, -1)\n    values = (rows.float() / scale).clamp(-QFM_FP8_MAX, QFM_FP8_MAX).to(torch.float8_e4m3fn)\n    torch_npu.npu_scatter_pa_cache(values.reshape(-1, 1, QFM_TILE).contiguous(), offsets.flatten(), key_cache=alias)\n\n\ndef load_ops():\n    # Load only after selecting the worker device. Never catch kernel failures.\n    importlib.import_module("cann_ops_transformer.ops")\n    return torch.ops.cann_ops_transformer.quant_flash_mla, torch.ops.cann_ops_transformer.quant_flash_mla_metadata\n\n\n@dataclass\nclass QFMBatch:\n    cu: torch.Tensor\n    used: torch.Tensor\n    lengths: torch.Tensor\n    table: torch.Tensor\n    slots: torch.Tensor\n    live: torch.Tensor\n    visible: torch.Tensor\n    schedule: torch.Tensor\n    mask: torch.Tensor | None\n    mask_mode: int\n    max_q: int\n    max_k: int\n    has_prefill: bool\n    # (query begin, query end, local history length, original request page table).\n    fia_requests: tuple = ()\n    qfm_needed: bool = True\n\n\nclass QFMMetadataBuilder:\n    def __init__(self, impl, device):\n        self.device = device\n        self.dcp_size = impl.vllm_config.parallel_config.decode_context_parallel_size\n        self.dcp_rank = getattr(impl, "dcp_rank", 0)\n        self.interleave = impl.vllm_config.parallel_config.cp_kv_cache_interleave_size\n        self.heads = impl.num_heads * self.dcp_size\n        self.max_k = max(1, impl.vllm_config.model_config.max_model_len)\n        _, self.metadata_op = load_ops()\n        self.mask = torch.ones((QFM_MASK, QFM_MASK), dtype=torch.int8, device=device).triu_(1)\n        self.buffers = {}\n        self.fia_prefill = getattr(impl, "qfm_fia_prefill", False)\n\n    def metadata(self, lengths, cu, used, max_q, mode):\n        return self.metadata_op(\n            lengths,\n            self.heads,\n            1,\n            1,\n            cu_seqlens_q=cu,\n            seqused_q=used,\n            max_seqlen_q=max_q,\n            max_seqlen_kv=self.max_k,\n            head_dim_qk=QFM_WIDTH,\n            head_dim_v=QFM_VALUE,\n            mask_mode=mode,\n            layout_q="TND",\n        )\n\n    def build(self, common, retain_for_graph=False):\n        tokens = max(common.num_actual_tokens, common.num_input_tokens)\n        # These are already KERNEL-page columns from MRV2 BlockTables, even\n        # when the final cache manager uses 256/512/... token blocks.\n        columns = common.block_table_tensor.shape[1]\n        key = tokens, columns, common.causal\n        batch = self.buffers.get(key)\n        # All decode graph capacities use one physical query per virtual row.\n        # Eager prefill batches use <=16 rows per sequence, NOT small op calls.\n        per_token = retain_for_graph or batch is not None or self.dcp_size > 1\n        if per_token:\n            cu_cpu = list(range(tokens + 1))\n        else:\n            bounds = common.query_start_loc_cpu[: common.num_reqs + 1].clamp_max(common.num_actual_tokens).tolist()\n            cu_cpu = [0]\n            for begin, end in zip(bounds, bounds[1:]):\n                while begin < end:\n                    begin = min(begin + QFM_MAX_Q, end)\n                    cu_cpu.append(begin)\n            while cu_cpu[-1] < tokens:\n                cu_cpu.append(min(cu_cpu[-1] + QFM_MAX_Q, tokens))\n        rows = len(cu_cpu) - 1\n        if not 0 < rows < 65536:\n            raise ValueError("QFM virtual batch must contain 1..65535 rows")\n        mode = 0 if per_token or not common.causal else 3\n        ints = dict(dtype=torch.int32, device=self.device)\n        if batch is None:\n            cu = torch.tensor(cu_cpu, **ints)\n            used, lengths = torch.zeros(rows, **ints), torch.zeros(rows, **ints)\n            # Populate once after device lengths are ready. Do not invoke the\n            # scheduling kernel twice or require a separate Meta registration.\n            schedule = torch.empty(0, **ints)\n            batch = QFMBatch(\n                cu,\n                used,\n                lengths,\n                torch.zeros((rows, columns), **ints),\n                torch.full((tokens,), -1, dtype=torch.int64, device=self.device),\n                torch.zeros(tokens, dtype=torch.bool, device=self.device),\n                torch.zeros(tokens, dtype=torch.bool, device=self.device),\n                schedule,\n                self.mask if mode == 3 else None,\n                mode,\n                1 if per_token else QFM_MAX_Q,\n                self.max_k,\n                False,\n            )\n            if retain_for_graph:\n                self.buffers[key] = batch\n        # Only device lengths: DSpark rejection correction may not be mirrored\n        # to CPU. Updates are on the caller\'s stream before graph replay.\n        boundaries = common.query_start_loc[: common.num_reqs + 1].contiguous()\n        token_ids = torch.arange(tokens, device=self.device, dtype=torch.int32)\n        owners = torch.searchsorted(boundaries[1:], token_ids, right=True).clamp_max(common.num_reqs - 1).long()\n        starts, ends = boundaries[owners], boundaries[owners + 1]\n        seq = common.seq_lens[owners]\n        live = (token_ids < common.num_actual_tokens) & (token_ids < ends) & (seq > 0)\n        batch.live.copy_(live)\n        batch.slots.fill_(-1)\n        count = min(tokens, common.slot_mapping.numel())\n        batch.slots[:count].copy_(common.slot_mapping[:count])\n        batch.slots.masked_fill_(~live, -1)\n        lengths_per_token = seq - (ends - starts) + token_ids - starts + 1 if common.causal else seq\n        if self.dcp_size > 1:\n            cycle = self.interleave * self.dcp_size\n            lengths_per_token = lengths_per_token.div(cycle, rounding_mode="floor") * self.interleave + (\n                lengths_per_token.remainder(cycle) - self.dcp_rank * self.interleave\n            ).clamp(0, self.interleave)\n        lengths_per_token = torch.where(live, lengths_per_token.clamp_min(0), 0)\n        batch.visible.copy_(live & (lengths_per_token > 0))\n        first = batch.cu[:-1].long()\n        row_owner = owners[first]\n        row_used = (ends[first] - batch.cu[:-1]).clamp_min(0)\n        row_used = torch.minimum(row_used, batch.cu[1:] - batch.cu[:-1])\n        row_used = torch.where(live[first], row_used, 0)\n        last = (batch.cu[:-1] + row_used - 1).clamp_min(0).long()\n        batch.used.copy_(row_used)\n        batch.lengths.copy_(torch.where(row_used > 0, lengths_per_token[last], 0))\n        batch.table.copy_(common.block_table_tensor[row_owner])\n        flags = common.is_prefilling\n        if flags is not None and flags.device.type != "cpu":\n            raise ValueError("QFM expects scheduler CPU stage flags, not a device-to-host sync")\n        batch.fia_requests = ()\n        batch.qfm_needed = True\n        if self.fia_prefill:\n            if flags is None:\n                raise ValueError("FIA Prefill routing requires explicit scheduler stage flags")\n            selected = flags[: common.num_reqs].bool()\n            if bool(selected.any()):\n                if retain_for_graph or batch is self.buffers.get(key):\n                    raise ValueError("FIA Prefill is eager only; Decode-only graphs remain supported")\n                if not common.causal:\n                    raise ValueError("FIA Prefill currently requires causal attention")\n                # One metadata-time host synchronization, never once per layer.\n                # Device lengths include DSpark corrections that CPU mirrors may miss.\n                seq_cpu = common.seq_lens[: common.num_reqs].detach().cpu().tolist()\n                bounds = common.query_start_loc_cpu[: common.num_reqs + 1].tolist()\n                requests = []\n                for owner in selected.nonzero().flatten().tolist():\n                    begin, end = bounds[owner : owner + 2]\n                    if begin == end:\n                        continue\n                    history = seq_cpu[owner] - (end - begin)\n                    if history < 0 or end > common.num_actual_tokens:\n                        raise ValueError("Inconsistent FIA Prefill query/history lengths")\n                    cycle = self.interleave * self.dcp_size\n                    local_history = (history // cycle) * self.interleave + min(\n                        max(history % cycle - self.dcp_rank * self.interleave, 0), self.interleave\n                    )\n                    requests.append((begin, end, local_history, common.block_table_tensor[owner]))\n                batch.fia_requests = tuple(requests)\n                selected_device = selected.to(self.device)\n                skip = selected_device[row_owner]\n                batch.used.masked_fill_(skip, 0)\n                batch.lengths.masked_fill_(skip, 0)\n                batch.qfm_needed = not bool(selected.all())\n        schedule = self.metadata(batch.lengths, batch.cu, batch.used, batch.max_q, mode)\n        if batch.schedule.numel() == 0:\n            batch.schedule = schedule\n        else:\n            batch.schedule.copy_(schedule)\n        batch.has_prefill = bool(flags[: common.num_reqs].any()) if flags is not None else common.max_query_len > 16\n        return batch\n\n\ndef read_fia_history(cache, table, length, scale):\n    """Gather only live history, preserving NZ strides and storage offset.\n\n    Index FP8 as bytes (advanced FP8 indexing is not supported everywhere).\n    The result is temporary BF16 latent512+raw64, not a second cache pool.\n    """\n    position = torch.arange(length, device=cache.device)\n    pages = table[position.div(QFM_BLOCK, rounding_mode="floor")].long()\n    tiles = torch.arange(QFM_WIDTH // QFM_TILE, device=cache.device)\n    packed = cache.view(torch.uint8)[pages[:, None], 0, tiles[None, :], position.remainder(QFM_BLOCK)[:, None], :]\n    return (packed.view(torch.float8_e4m3fn).reshape(length, 1, QFM_WIDTH).float() * scale).to(torch.bfloat16)\n\n\ndef fia_partial(q, kv, scale, mask=None):\n    """Use the same latent512/raw64 TND FIA-v2 contract as MLA CP."""\n    if kv.shape[0] == 0:\n        return (\n            torch.zeros((*q.shape[:2], QFM_VALUE), dtype=torch.bfloat16, device=q.device),\n            torch.full((*q.shape[:2], 1), -float("inf"), device=q.device),\n        )\n    latent = kv[..., :QFM_VALUE].contiguous()\n    output, lse = torch_npu.npu_fused_infer_attention_score_v2(\n        q[..., :QFM_VALUE].to(torch.bfloat16).contiguous(),\n        latent,\n        latent,\n        query_rope=q[..., QFM_VALUE:].to(torch.bfloat16).contiguous(),\n        key_rope=kv[..., QFM_VALUE:].contiguous(),\n        num_query_heads=q.shape[1],\n        num_key_value_heads=1,\n        input_layout="TND",\n        atten_mask=mask,\n        sparse_mode=3 if mask is not None else 0,\n        softmax_scale=scale,\n        actual_seq_qlen=[q.shape[0]],\n        actual_seq_kvlen=[kv.shape[0]],\n        return_softmax_lse=True,\n    )\n    # FIA-v2 TND returns token-major output and token-major LSE.\n    return output.reshape(q.shape[0], q.shape[1], QFM_VALUE), lse.reshape(q.shape[0], q.shape[1], 1)\n\n\ndef merge_fia_parts(left, right):\n    """Combine independently normalized Attention outputs in natural-log space."""\n    a, la = left\n    b, lb = right\n    total = torch.logaddexp(la, lb)\n    # Empty+empty has -inf LSE: replace NaN weights with zero.\n    wa = torch.nan_to_num(torch.exp(la - total), nan=0.0)\n    wb = torch.nan_to_num(torch.exp(lb - total), nan=0.0)\n    return (a.float() * wa + b.float() * wb).to(a.dtype), total\n\n\ndef fill_fia_prefill(impl, q, kv, cache, batch, latent, lse):\n    """History is local FP8; current floating KV contributes on DCP rank zero.\n\n    All ranks run the same final DCP merge. No per-query FIA loops, no dense\n    Q-by-history index lists. Process one request at a time to bound workspace.\n    """\n    mask = torch.ones((QFM_MASK, QFM_MASK), dtype=torch.bool, device=q.device).triu_(1)\n    for begin, end, history_length, table in batch.fia_requests:\n        query = q[begin:end]\n        history = read_fia_history(cache, table, history_length, impl.qfm_scale)\n        result = fia_partial(query, history, impl.scale)\n        del history\n        if not impl.dcp_enabled or impl.dcp_rank == 0:\n            current = kv[begin:end].reshape(end - begin, 1, QFM_WIDTH).to(torch.bfloat16)\n            result = merge_fia_parts(result, fia_partial(query, current, impl.scale, mask))\n        latent[begin:end].copy_(result[0])\n        lse[begin:end].copy_(result[1])\n\n\ndef forward_qfm(impl, hidden, cache, metadata, output):\n    """Keep existing quantized Linear modules; only KV storage/reader change."""\n    batch = metadata.qfm\n    if batch is None:\n        raise RuntimeError("QFM selected but QFM metadata is missing")\n    tokens = batch.slots.numel()\n    if impl.fused_qkv_a_proj is not None:\n        projected = impl.fused_qkv_a_proj(hidden)[0]\n        q, kv = projected.split([impl.q_lora_rank, QFM_WIDTH], dim=-1)\n        q = impl.q_a_layernorm(q)\n    else:\n        q, kv = hidden, impl.kv_a_proj_with_mqa(hidden)[0]\n    if q.shape[0] < tokens or kv.shape[0] < tokens:\n        raise ValueError("QFM projected inputs do not cover physical graph capacity")\n    q, kv = q[:tokens], kv[:tokens]\n    q_nope, q_raw = impl._q_proj_and_k_up_proj(q)\n    q = torch.cat((q_nope, q_raw), dim=-1)\n    latent, raw = kv.split([QFM_VALUE, QFM_WIDTH - QFM_VALUE], dim=-1)\n    kv = torch.cat((impl.kv_a_layernorm(latent.contiguous()), raw), dim=-1)\n    write_cache(kv, batch.slots, cache, impl.qfm_scale)\n    if impl.dcp_enabled:\n        q = impl._dcp_all_gather(q, dim=1)\n    if batch.qfm_needed:\n        latent, lse = run_qfm_reader(impl, q, cache, batch)\n    else:\n        latent = torch.zeros((*q.shape[:2], QFM_VALUE), dtype=q.dtype, device=q.device)\n        lse = torch.full((*q.shape[:2], 1), -float("inf"), device=q.device)\n    if batch.fia_requests:\n        fill_fia_prefill(impl, q, kv, cache, batch, latent, lse)\n    if impl.dcp_enabled:\n        latent = impl._merge_dcp_attention_output(latent, lse)\n    projected = impl._v_up_proj_batch_major(latent)\n    projected = projected.masked_fill(~batch.live[:, None], 0)\n    if impl.use_output_gate:\n        projected = projected * torch.sigmoid(impl.g_proj(hidden.contiguous())[0][:tokens])\n    result = impl.o_proj(projected, is_prefill=batch.has_prefill)[0]\n    output.copy_(result)\n    return output\n\n\ndef run_qfm_reader(impl, q, cache, batch):\n    q_scale = q.float().abs().amax(-1).clamp_min(1e-12) / QFM_FP8_MAX\n    q8 = (q.float() / q_scale[..., None]).clamp(-QFM_FP8_MAX, QFM_FP8_MAX).to(torch.float8_e4m3fn)\n    attention, _ = impl.qfm_ops\n    latent, lse = attention(\n        q8,\n        cache,\n        q_scale,\n        impl.qfm_scale,\n        batch.table,\n        batch.lengths,\n        1,\n        cu_seqlens_q=batch.cu,\n        seqused_q=batch.used,\n        metadata=batch.schedule,\n        head_dim_v=QFM_VALUE,\n        attn_mask=batch.mask,\n        softmax_scale=impl.scale,\n        mask_mode=batch.mask_mode,\n        max_seqlen_q=batch.max_q,\n        max_seqlen_kv=batch.max_k,\n        layout_q="TND",\n        layout_kv="PA_NZ",\n        layout_out="TND",\n        return_softmax_lse=impl.dcp_enabled,\n    )\n    latent = latent.masked_fill(~batch.visible[:, None, None], 0)\n    if impl.dcp_enabled:\n        lse = lse.T.masked_fill(~batch.visible[:, None], -float("inf")).unsqueeze(-1)\n    elif batch.fia_requests:\n        lse = torch.empty((*q.shape[:2], 1), device=q.device)\n    return latent, lse\n', 'prolog_reference': '# SPDX-License-Identifier: Apache-2.0\n"""Single-NPU synthetic check of the standalone K3 QFM Prolog adapter.\n\nExample: python check_kimi_k3_qfm_prolog.py --device 0 --graph\nThe isolated ``kimi_k3_quant_mla_prolog`` package must already be installed.\nNo model weights, vLLM runtime, downloads, or multi-NPU claims are involved.\n\nThe CPU equations and two-way acceptance thresholds were checked against:\ncann/cannbot-dsl@9e01355ab8f809050579271c0eadcc5858ed20bc,\ntest/quant_mla_prolog/test_quant_mla_prolog.py. This probe deliberately does\nnot accept the upstream three-way/warning fallback or index-zero loophole.\n"""\n\nimport argparse\nimport importlib.util\nimport json\nimport sys\nimport traceback\nimport types\nfrom pathlib import Path\n\nHIDDEN = 1024\nQ_RANK = 640\nKV_RANK = 512\nNOPE = 128\nRAW = 64\nWIDTH = KV_RANK + RAW\nPAGE = 128\nTILE = 32\nBLOCKS = 4\nOFFSET = 256\nFP8_MAX = 448.0\nEPSILON = 1e-6\nSOURCE_PIN = "9e01355ab8f809050579271c0eadcc5858ed20bc"\n\n\ndef emit(event, **fields):\n    print(json.dumps({"event": event, **fields}, allow_nan=False), flush=True)\n\n\ndef require(condition, message):\n    if not condition:\n        raise AssertionError(message)\n\n\ndef load_adapter():\n    """Load only the two files; do not initialize vLLM/Ascend plugin imports."""\n    directory = Path(__file__).resolve().parents[6] / "vllm_ascend" / "attention"\n    package_name = "vllm_ascend.attention"\n    for name, path in (("vllm_ascend", directory.parent), (package_name, directory)):\n        package = types.ModuleType(name)\n        package.__path__ = [str(path)]\n        sys.modules[name] = package\n    for leaf in ("kimi_k3_qfm", "kimi_k3_qfm_prolog"):\n        name = f"{package_name}.{leaf}"\n        spec = importlib.util.spec_from_file_location(name, directory / f"{leaf}.py")\n        module = importlib.util.module_from_spec(spec)\n        sys.modules[name] = module\n        spec.loader.exec_module(module)\n    return module.QFMProlog\n\n\ndef mx_quantize(torch, torch_npu, values, device):\n    data, scale = torch_npu.npu_dynamic_mx_quant(\n        values.to(device=device, dtype=torch.bfloat16).contiguous(), dst_type=torch.float8_e4m3fn, scale_alg=0\n    )\n    # View the exponent bytes, never numerically cast E8M0 through BF16.\n    scale = scale.view(torch.uint8).reshape(values.shape[0], values.shape[1] // 64, 2)\n    return data, scale.contiguous().view(torch.float8_e8m0fnu)\n\n\ndef make_weights(torch, torch_npu, heads, device):\n    generator = torch.Generator().manual_seed(1463 + heads)\n    result = {"norm_eps": EPSILON}\n    for name, rows, columns in (\n        ("wqa", Q_RANK, HIDDEN),\n        ("wqb", heads * (NOPE + RAW), Q_RANK),\n        ("wkva", WIDTH, HIDDEN),\n    ):\n        groups = torch.arange(columns // TILE)[None, :]\n        channels = torch.arange(rows)[:, None]\n        varying = torch.exp2(((channels + groups) % 5 - 2).float()).repeat_interleave(TILE, dim=1)\n        values = torch.randn(rows, columns, generator=generator) * 0.05 * varying\n        result[name], result[f"descale_{name}"] = mx_quantize(torch, torch_npu, values, device)\n    result["wkb"] = (torch.randn(heads, NOPE, KV_RANK, generator=generator) * 0.02).to(\n        device=device, dtype=torch.bfloat16\n    )\n    for name, size in (("norm_weight_qa", Q_RANK), ("norm_weight_kva", KV_RANK)):\n        result[name] = (1 + torch.randn(size, generator=generator) * 0.1).bfloat16().float().to(device)\n    return result\n\n\ndef decode_mx(torch, data, scale):\n    """Independent CPU E8M0 decoder and logical Group32 expansion."""\n    raw = scale.detach().cpu().contiguous().view(torch.uint8)\n    require(not bool((raw == 255).any()), "Synthetic MX scale unexpectedly contains NaN")\n    powers = torch.exp2(raw.float().reshape(data.shape[0], -1) - 127)\n    return data.detach().cpu().float() * powers.repeat_interleave(TILE, dim=-1)\n\n\ndef normalized_mx(torch, values):\n    """CPU norm-output BF16 ties-away boundary followed by MX32 quantization."""\n    words = values.float().contiguous().view(torch.int32).to(torch.int64)\n    rounded = ((words + 32768) >> 16).to(torch.int16).view(torch.bfloat16).float()\n    blocks = rounded.reshape(rounded.shape[0], -1, TILE)\n    maximum = blocks.abs().amax(-1)\n    zero = maximum < torch.finfo(torch.bfloat16).tiny\n    _, exponent = torch.frexp(torch.where(zero, torch.ones_like(maximum), maximum))\n    raw_scale = (exponent + 118).clamp(0, 254)\n    scale = torch.exp2(raw_scale.float() - 127)\n    inverse = torch.where(zero, torch.zeros_like(scale), scale.reciprocal())\n    normalized = (blocks * inverse[..., None]).bfloat16().float()\n    encoded = normalized.clamp(-FP8_MAX, FP8_MAX).to(torch.float8_e4m3fn)\n    return (encoded.float() * scale[..., None]).reshape_as(values)\n\n\ndef cpu_reference(torch, torch_npu, hidden, weights, kv_scale):\n    # Input quantization is the same public primitive used by the adapter; all\n    # projection, norm, absorb, output quantization and cache-layout oracles are CPU.\n    x, sx = mx_quantize(torch, torch_npu, hidden, hidden.device)\n    x = decode_mx(torch, x, sx)\n    matrices = {name: decode_mx(torch, weights[name], weights[f"descale_{name}"]) for name in ("wqa", "wqb", "wkva")}\n\n    def rms(values, gamma):\n        return values / torch.sqrt(values.square().mean(-1, keepdim=True) + EPSILON) * gamma.cpu().float()\n\n    qa = normalized_mx(torch, rms(x @ matrices["wqa"].T, weights["norm_weight_qa"]))\n    heads = weights["wkb"].shape[0]\n    qb = (qa @ matrices["wqb"].T).reshape(hidden.shape[0], heads, NOPE + RAW)\n    absorbed = torch.einsum("thd,hdk->thk", qb[..., :NOPE].bfloat16().float(), weights["wkb"].cpu().float())\n    q_bf16 = torch.cat((absorbed.bfloat16(), qb[..., NOPE:].bfloat16()), dim=-1)\n    q_scale = q_bf16.float().abs().amax(-1) / FP8_MAX\n    divisor = torch.where(q_scale == 0, torch.ones_like(q_scale), q_scale)\n    q_fp8 = (q_bf16.float() / divisor[..., None]).clamp(-FP8_MAX, FP8_MAX).to(torch.float8_e4m3fn)\n    projected = x @ matrices["wkva"].T\n    cache_unquantized = torch.cat(\n        (rms(projected[:, :KV_RANK], weights["norm_weight_kva"]), projected[:, KV_RANK:].bfloat16().float()), dim=-1\n    )\n    cache_fp8 = (cache_unquantized / kv_scale).clamp(-FP8_MAX, FP8_MAX).to(torch.float8_e4m3fn)\n    return {\n        "q": q_fp8,\n        "q_scale": q_scale,\n        "q_bf16": q_bf16,\n        "cache": cache_fp8,\n        "cache_unquantized": cache_unquantized,\n    }\n\n\ndef numeric_metrics(torch, actual, expected):\n    actual, expected = actual.float(), expected.float()\n    finite = bool(torch.isfinite(actual).all() and torch.isfinite(expected).all())\n    if not finite:\n        return {\n            "all_finite": False,\n            "relative_l2": None,\n            "max_abs": None,\n            "nonfinite_actual": int((~torch.isfinite(actual)).sum()),\n            "nonfinite_expected": int((~torch.isfinite(expected)).sum()),\n        }\n    # Keep diagnostic reductions finite even when finite FP32 values are large.\n    actual, expected = actual.double(), expected.double()\n    difference = actual - expected\n    return {\n        "all_finite": True,\n        "relative_l2": float(difference.norm() / expected.norm().clamp_min(1e-12)),\n        "max_abs": float(difference.abs().max()) if difference.numel() else 0.0,\n    }\n\n\ndef encoded_check(torch, actual, expected, name):\n    """Upstream FP8 two-way thresholds, with a strict hard cap at index zero too."""\n    require(actual.shape == expected.shape, f"{name}: shape mismatch")\n    finite = bool(torch.isfinite(actual.float()).all() and torch.isfinite(expected.float()).all())\n    a = actual.contiguous().view(torch.uint8).to(torch.int16)\n    b = expected.contiguous().view(torch.uint8).to(torch.int16)\n    difference = (a - b).abs()\n    distance = torch.minimum(difference, 256 - difference)\n    signed_zero = ((a == 0) & (b == 128)) | ((a == 128) & (b == 0))\n    bad = int((distance > 1).sum())\n    hard_bad = int(((distance > 2) & ~signed_zero).sum())\n    result = {\n        "name": name,\n        "bad_codes": bad,\n        "allowed_bad_codes": a.numel() // 200,\n        "hard_bad_codes": hard_bad,\n        "max_code_distance": int(distance.max()) if distance.numel() else 0,\n        "all_finite": finite,\n        "pass": finite and bad <= a.numel() // 200 and hard_bad == 0,\n    }\n    emit("encoded_check", **result)\n    return result["pass"]\n\n\ndef scale_check(torch, actual, expected):\n    require(actual.shape == expected.shape, "Q descale shape mismatch")\n    valid = bool(torch.isfinite(actual).all() and torch.isfinite(expected).all() and (actual >= 0).all())\n    bad = int((~torch.isclose(actual, expected, atol=0.000025, rtol=0.005)).sum())\n    result = {\n        "bad_elements": bad,\n        "allowed_bad_elements": actual.numel() // 200,\n        "atol": 0.000025,\n        "rtol": 0.005,\n        "valid_descales": valid,\n        "pass": valid and bad <= actual.numel() // 200,\n    }\n    emit("scale_check", **result)\n    return result["pass"]\n\n\ndef make_slots(torch, tokens, changed=False):\n    if tokens == 1:\n        slots = torch.tensor([127], dtype=torch.int64)\n    elif tokens <= 9:\n        slots = torch.tensor([-1, 127, 128, 511, 255, 256, 1, 383, 384][:tokens], dtype=torch.int64)\n    else:\n        slots = torch.arange(tokens, dtype=torch.int64) + 127\n        slots[0], slots[-1] = -1, BLOCKS * PAGE - 1\n    if changed:\n        slots = torch.where(slots < 0, slots, (slots + 17) % (BLOCKS * PAGE))\n    return slots\n\n\ndef cache_buffer(torch, device, gap):\n    stride = PAGE * WIDTH + gap\n    initial = torch.full((OFFSET + BLOCKS * stride + OFFSET,), 0x35, dtype=torch.uint8)\n    initial[:OFFSET].fill_(0xA5)\n    initial[-OFFSET:].fill_(0xA5)\n    backing = initial.to(device)\n    raw = backing[OFFSET:-OFFSET].view(torch.float8_e4m3fn)\n    cache = torch.as_strided(raw, (BLOCKS, 1, WIDTH // TILE, PAGE, TILE), (stride, PAGE * WIDTH, PAGE * TILE, TILE, 1))\n    return initial, backing, cache\n\n\ndef check_result(torch, q, q_scale, cache, backing, initial, slots, reference, kv_scale, draft, draft_initial):\n    require(q.dtype == torch.float8_e4m3fn and q_scale.dtype == torch.float32, "Wrong Q/scale dtype")\n    require(q.shape == reference["q"].shape, "Wrong Q shape")\n    q_cpu, scale_cpu = q.detach().cpu(), q_scale.detach().cpu()\n    checks = {\n        "q_encoded": encoded_check(torch, q_cpu, reference["q"], "Q"),\n        "q_scale": scale_check(torch, scale_cpu, reference["q_scale"]),\n    }\n    after = backing.cpu()\n    changed = torch.zeros_like(after, dtype=torch.bool)\n    cache_rows = []\n    stride = cache.stride(0)\n    for slot in slots.tolist():\n        if slot < 0:\n            continue\n        block, row = divmod(slot, PAGE)\n        start = OFFSET + block * stride\n        tile = after[start : start + PAGE * WIDTH].view(WIDTH // TILE, PAGE, TILE)\n        cache_rows.append(tile[:, row, :].contiguous().view(torch.float8_e4m3fn).reshape(WIDTH))\n        changed[start : start + PAGE * WIDTH].view(WIDTH // TILE, PAGE, TILE)[:, row, :] = True\n    checks["untouched_cache_and_guards"] = torch.equal(after[~changed], initial[~changed])\n    checks["separate_draft"] = torch.equal(draft.cpu(), draft_initial)\n    valid = slots >= 0\n    if cache_rows:\n        actual_cache = torch.stack([row.view(torch.uint8) for row in cache_rows]).view(torch.float8_e4m3fn)\n        expected_cache = reference["cache"].view(torch.uint8)[valid].contiguous().view(torch.float8_e4m3fn)\n        checks["cache_encoded"] = encoded_check(torch, actual_cache, expected_cache, "Cache")\n        cache_metrics = {\n            "same_stored_fp8_reference": numeric_metrics(\n                torch, actual_cache.float() * kv_scale, expected_cache.float() * kv_scale\n            ),\n            "unquantized_reference": numeric_metrics(\n                torch, actual_cache.float() * kv_scale, reference["cache_unquantized"][valid]\n            ),\n        }\n        emit("cache_numeric", **cache_metrics)\n        checks["cache_numeric_finite"] = all(metric["all_finite"] for metric in cache_metrics.values())\n    reconstructed = q_cpu.float() * scale_cpu[..., None]\n    query_metrics = {\n        "same_quantized_reference": numeric_metrics(\n            torch, reconstructed, reference["q"].float() * reference["q_scale"][..., None]\n        ),\n        "bf16_pre_output_quant_reference": numeric_metrics(torch, reconstructed, reference["q_bf16"]),\n        "expected_fp8_quantization_loss": numeric_metrics(\n            torch, reference["q"].float() * reference["q_scale"][..., None], reference["q_bf16"]\n        ),\n    }\n    emit("query_numeric", **query_metrics)\n    checks["query_numeric_finite"] = all(metric["all_finite"] for metric in query_metrics.values())\n    emit(\n        "cache_guards",\n        offset_bytes=OFFSET,\n        page_padding_bytes=stride - PAGE * WIDTH,\n        negative_slots=int((~valid).sum()),\n        separate_draft_unchanged=checks["separate_draft"],\n        untouched_cache_and_guards=checks["untouched_cache_and_guards"],\n        **{"pass": checks["separate_draft"] and checks["untouched_cache_and_guards"]},\n    )\n    emit("result_checks", checks=checks, **{"pass": all(checks.values())})\n    failed = [name for name, passed in checks.items() if not passed]\n    require(not failed, f"Prolog checks failed: {\', \'.join(failed)}; full diagnostics emitted above")\n\n\ndef check_qfm_roundtrip(torch, q, q_scale, cache, slots, kv_scale):\n    """Run the native reader on Prolog bytes; oracle uses those same bytes.\n\n    Synthetic per-query prefixes use a reversed physical page table, so tests\n    cannot pass by accidentally treating logical pages as physical pages.\n    Prolog-vs-golden is independently checked above, not hidden by this oracle.\n    """\n    importlib.import_module("cann_ops_transformer.ops")\n    native = torch.ops.cann_ops_transformer\n    live_cpu = (slots >= 0).nonzero().flatten()\n    require(live_cpu.numel() > 0, "Roundtrip needs at least one valid writer slot")\n    live = live_cpu.to(q.device)\n    query = q.view(torch.uint8)[live].contiguous().view(torch.float8_e4m3fn)\n    descale = q_scale[live].contiguous()\n    selected_slots = slots[live_cpu]\n    lengths_cpu = (BLOCKS - 1 - selected_slots // PAGE) * PAGE + selected_slots % PAGE + 1\n    count, heads = query.shape[:2]\n    lengths = lengths_cpu.to(device=q.device, dtype=torch.int32)\n    cu = torch.arange(count + 1, dtype=torch.int32, device=q.device)\n    used = torch.ones(count, dtype=torch.int32, device=q.device)\n    table = torch.arange(BLOCKS - 1, -1, -1, dtype=torch.int32, device=q.device).repeat(count, 1)\n    scale = torch.tensor([kv_scale], dtype=torch.float32, device=q.device)\n    before = cache.cpu().view(torch.uint8).clone()\n    emit("stage", name="qfm_metadata", status="begin", query_tokens=count)\n    schedule = native.quant_flash_mla_metadata(\n        lengths,\n        heads,\n        1,\n        1,\n        cu_seqlens_q=cu,\n        seqused_q=used,\n        max_seqlen_q=1,\n        max_seqlen_kv=BLOCKS * PAGE,\n        head_dim_qk=WIDTH,\n        head_dim_v=KV_RANK,\n        mask_mode=0,\n        layout_q="TND",\n    )\n    emit("stage", name="qfm_attention", status="begin")\n    output, lse = native.quant_flash_mla(\n        query,\n        cache,\n        descale,\n        scale,\n        table,\n        lengths,\n        1,\n        cu_seqlens_q=cu,\n        seqused_q=used,\n        metadata=schedule,\n        head_dim_v=KV_RANK,\n        softmax_scale=WIDTH**-0.5,\n        mask_mode=0,\n        max_seqlen_q=1,\n        max_seqlen_kv=BLOCKS * PAGE,\n        layout_q="TND",\n        layout_kv="PA_NZ",\n        layout_out="TND",\n        return_softmax_lse=True,\n    )\n    torch.npu.synchronize()\n    physical = cache.cpu().float()[:, 0].permute(0, 2, 1, 3).reshape(BLOCKS, PAGE, WIDTH)\n    keys = physical.flip(0).reshape(-1, WIDTH) * kv_scale\n    queries = query.cpu().float() * descale.cpu()[..., None]\n    expected, expected_lse = [], []\n    for index, length in enumerate(lengths_cpu.tolist()):\n        scores = queries[index] @ keys[:length].T * WIDTH**-0.5\n        expected.append(scores.softmax(-1) @ keys[:length, :KV_RANK])\n        expected_lse.append(scores.logsumexp(-1))\n    expected = torch.stack(expected)\n    expected_lse = torch.stack(expected_lse)\n    actual, actual_lse = output.cpu().float(), lse.cpu().T.float()\n    metrics = numeric_metrics(torch, actual, expected)\n    # Explicit fixed numerical gates; do not auto-relax on failures.\n    output_ok = (\n        metrics["all_finite"]\n        and metrics["relative_l2"] <= 0.03\n        and bool(torch.isclose(actual, expected, atol=0.04, rtol=0.03).all())\n    )\n    lse_ok = bool(torch.isclose(actual_lse, expected_lse, atol=0.002, rtol=0.001).all())\n    unchanged = torch.equal(cache.cpu().view(torch.uint8), before)\n    emit(\n        "qfm_roundtrip",\n        **metrics,\n        output_pass=output_ok,\n        lse_pass=lse_ok,\n        cache_unchanged=unchanged,\n        reference="FP32 on actual Prolog FP8 Q/KV and descales",\n        **{"pass": output_ok and lse_ok and unchanged},\n    )\n    require(output_ok and lse_ok and unchanged, "Prolog -> QFM numerical roundtrip failed")\n\n\ndef run_case(torch, torch_npu, adapter_class, weights, heads, tokens, gap, device, graph=False):\n    def begin(phase, **fields):\n        emit(\n            "case_begin",\n            heads=heads,\n            tokens=tokens,\n            gap=gap,\n            graph=graph,\n            hidden_dim=HIDDEN,\n            q_rank=Q_RANK,\n            offset_bytes=OFFSET,\n            phase=phase,\n            **fields,\n        )\n\n    begin("prepare_reference")\n    generator = torch.Generator().manual_seed(202611 + heads + tokens)\n    hidden = (torch.randn(tokens, HIDDEN, generator=generator) * 0.3).to(device=device, dtype=torch.bfloat16)\n    slots_cpu = make_slots(torch, tokens)\n    slots = slots_cpu.to(device)\n    kv_scale = 1.0  # Adapter intentionally admits only the recipe\'s unit descale.\n    scale = torch.tensor([kv_scale], dtype=torch.float32, device=device)\n    adapter = adapter_class(weights, scale)\n    initial, backing, cache = cache_buffer(torch, device, gap)\n    draft_initial = torch.full_like(initial, 0x6A)\n    draft = draft_initial.to(device)\n    reference = cpu_reference(torch, torch_npu, hidden, weights, kv_scale)\n    pointer, storage_pointer = cache.data_ptr(), cache.untyped_storage().data_ptr()\n    begin("eager")\n    q, q_scale = adapter(hidden, slots, cache)\n    torch.npu.synchronize()\n    require(\n        cache.data_ptr() == pointer and cache.untyped_storage().data_ptr() == storage_pointer,\n        "Writer replaced caller-owned cache storage",\n    )\n    check_result(torch, q, q_scale, cache, backing, initial, slots_cpu, reference, kv_scale, draft, draft_initial)\n    check_qfm_roundtrip(torch, q, q_scale, cache, slots_cpu, kv_scale)\n    if graph:\n        for iteration in range(2):\n            begin("graph_warmup", iteration=iteration)\n            adapter(hidden, slots, cache)\n        torch.npu.synchronize()\n        captured = torch.npu.NPUGraph()\n        begin("graph_capture")\n        with torch.npu.graph(captured):\n            graph_q, graph_scale = adapter(hidden, slots, cache)\n        for changed in (False, True):\n            if changed:\n                hidden.copy_(\n                    (torch.randn(tokens, HIDDEN, generator=generator) * 0.4).to(device=device, dtype=torch.bfloat16)\n                )\n                slots_cpu = make_slots(torch, tokens, changed=True)\n                slots.copy_(slots_cpu.to(device))\n                reference = cpu_reference(torch, torch_npu, hidden, weights, kv_scale)\n            backing.copy_(initial.to(device))\n            begin("graph_eager_reference", changed_hidden_and_slots=changed)\n            eager_q, eager_scale = adapter(hidden, slots, cache)\n            torch.npu.synchronize()\n            eager_q_cpu, eager_scale_cpu, eager_bytes = eager_q.cpu(), eager_scale.cpu(), backing.cpu()\n            backing.copy_(initial.to(device))\n            begin("graph_replay", changed_hidden_and_slots=changed)\n            captured.replay()\n            torch.npu.synchronize()\n            exact = {\n                "q": torch.equal(graph_q.cpu().view(torch.uint8), eager_q_cpu.view(torch.uint8)),\n                "q_scale": torch.equal(graph_scale.cpu(), eager_scale_cpu),\n                "cache": torch.equal(backing.cpu(), eager_bytes),\n            }\n            emit("graph_eager_exact", checks=exact, **{"pass": all(exact.values())})\n            check_result(\n                torch,\n                graph_q,\n                graph_scale,\n                cache,\n                backing,\n                initial,\n                slots_cpu,\n                reference,\n                kv_scale,\n                draft,\n                draft_initial,\n            )\n            require(all(exact.values()), f"Graph/eager exact comparison failed: {exact}")\n            check_qfm_roundtrip(torch, graph_q, graph_scale, cache, slots_cpu, kv_scale)\n        emit("graph_replay", changed_hidden_and_slots=True, fixed_shape=True, **{"pass": True})\n    emit("case_complete", heads=heads, tokens=tokens, gap=gap, graph=graph, **{"pass": True})\n\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--device", "--card", type=int, default=0)\n    parser.add_argument("--heads", nargs="+", type=int, choices=(12, 24, 48), default=[12, 24, 48])\n    parser.add_argument("--tokens", nargs="+", type=int, choices=(1, 4, 9, 128), default=[1, 4, 9])\n    parser.add_argument("--graph", action="store_true", help="Capture/replay the largest requested T with gaps0/256")\n    args = parser.parse_args(argv)\n    try:\n        # Lazy imports keep --help usable outside the target NPU environment.\n        import torch\n        import torch_npu\n\n        require(torch.npu.is_available(), "NPU unavailable; this probe cannot pass on CPU")\n        torch.npu.set_device(args.device)\n        device = f"npu:{args.device}"\n        adapter_class = load_adapter()\n        emit(\n            "environment",\n            device=torch.npu.get_device_name(args.device),\n            torch=torch.__version__,\n            torch_npu=getattr(torch_npu, "__version__", "unknown"),\n            reference_source_pin=SOURCE_PIN,\n            scope="single-NPU synthetic adapter; not a model/TP-collective acceptance test",\n        )\n        for heads in args.heads:\n            weights = make_weights(torch, torch_npu, heads, device)\n            try:\n                adapter_class(weights, torch.tensor([0.5], dtype=torch.float32, device=device))\n            except ValueError:\n                emit("nonunit_scale_rejected", heads=heads, **{"pass": True})\n            else:\n                raise AssertionError("Adapter unexpectedly accepted unsupported nonunit KV scale")\n            for tokens in args.tokens:\n                for gap in (0, OFFSET):\n                    run_case(\n                        torch,\n                        torch_npu,\n                        adapter_class,\n                        weights,\n                        heads,\n                        tokens,\n                        gap,\n                        device,\n                        graph=args.graph and tokens == max(args.tokens),\n                    )\n        emit("suite_complete", suite="kimi_k3_qfm_prolog", **{"pass": True})\n        return 0\n    except Exception as error:\n        traceback.print_exc()\n        emit("suite_complete", suite="kimi_k3_qfm_prolog", error=f"{type(error).__name__}: {error}", **{"pass": False})\n        return 1\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n', 'fia_prolog_worker': '"""Synthetic mode-0 Prolog -> current BF16 / persistent FP8 -> FIA probe."""\n\nimport importlib\nimport json\nfrom types import SimpleNamespace\n\n\ndef emit(event, **fields):\n    print(json.dumps({"event": event, **fields}, allow_nan=False), flush=True)\n\n\ndef check(torch, name, actual, expected, *, atol, rtol, l2_limit):\n    if actual.shape != expected.shape:\n        raise AssertionError(\n            f"{name}: shape mismatch {actual.shape} vs {expected.shape}"\n        )\n    a, b = actual.detach().cpu().float(), expected.detach().cpu().float()\n    finite = bool(torch.isfinite(a).all() and torch.isfinite(b).all())\n    l2 = (\n        float((a.double() - b.double()).norm() / b.double().norm().clamp_min(1e-12))\n        if finite\n        else None\n    )\n    bad = int((~torch.isclose(a, b, atol=atol, rtol=rtol)).sum())\n    passed = finite and l2 <= l2_limit and bad <= a.numel() // 200\n    emit(\n        "check",\n        name=name,\n        finite=finite,\n        relative_l2=l2,\n        bad_elements=bad,\n        allowed_bad_elements=a.numel() // 200,\n        atol=atol,\n        rtol=rtol,\n        l2_limit=l2_limit,\n        passed=passed,\n    )\n    if not passed:\n        raise AssertionError(f"{name} failed; thresholds unchanged")\n\n\ndef run(case, core, reference):\n    import torch\n    import torch_npu\n\n    torch.npu.set_device(0)\n    tokens, history_length, heads, gap, shards = case\n    device = "npu:0"\n    prolog = importlib.import_module("kimi_k3_quant_mla_prolog").quant_mla_prolog\n    torch.manual_seed(628)\n    emit("stage", name="weights_and_reference", case=case)\n    weights = reference.make_weights(torch, torch_npu, heads, device)\n    hidden = (torch.randn(tokens, reference.HIDDEN) * 0.3).bfloat16().to(device)\n    golden = reference.cpu_reference(torch, torch_npu, hidden, weights, 1.0)\n    x, sx = reference.mx_quantize(torch, torch_npu, hidden, device)\n    sx = sx.reshape(tokens, reference.HIDDEN // 32).contiguous()\n    # Mode 0 writes only current-token BF16 scratch, never a BF16 history pool.\n    offset = 256\n    scratch_pages = (tokens + 127) // 128\n    scratch_bytes = scratch_pages * 128 * 576 * 2\n    backing = torch.full(\n        (offset + scratch_bytes + offset,), 0x5A, dtype=torch.uint8, device=device\n    )\n    scratch = (\n        backing[offset:-offset].view(torch.bfloat16).view(scratch_pages, 128, 1, 576)\n    )\n    slots = torch.arange(tokens - 1, -1, -1, dtype=torch.int64, device=device)\n    emit("stage", name="prolog_mode0_compile_and_execute", tokens=tokens, heads=heads)\n    q, descale, _, _ = prolog(\n        x=x,\n        descale_x=sx,\n        kv_cache=scratch,\n        cache_index=slots,\n        quant_scale_kv=None,\n        w_qr_quant_mode=1,\n        qkv_quant_mode=0,\n        cache_mode=0,\n        rope_mode=0,\n        return_qr=False,\n        **weights,\n    )\n    torch.npu.synchronize()\n    if q.dtype != torch.bfloat16 or descale.numel() != 0:\n        raise AssertionError("Mode 0 must return BF16 Q without FP8 Q descales")\n    current = scratch.view(-1, 576)[slots].contiguous()\n    after = backing.cpu()\n    written_end = offset + tokens * 576 * 2\n    if not bool((after[:offset] == 0x5A).all() and (after[written_end:] == 0x5A).all()):\n        raise AssertionError("Prolog mode0 wrote outside current scratch slots")\n    check(\n        torch,\n        "mode0_Q_vs_projection_reference",\n        q,\n        golden["q_bf16"],\n        atol=0.04,\n        rtol=0.02,\n        l2_limit=0.01,\n    )\n    check(\n        torch,\n        "mode0_KV_vs_projection_reference",\n        current,\n        golden["cache_unquantized"].bfloat16(),\n        atol=0.02,\n        rtol=0.02,\n        l2_limit=0.01,\n    )\n    history_cpu = torch.randn(history_length, 576).bfloat16()\n    combined = torch.cat((history_cpu.to(device), current))\n    scale = torch.ones(1, dtype=torch.float32, device=device)\n    result = None\n    emit("stage", name="fp8_write_and_fia", simulated_shards=shards)\n    for rank in range(shards):\n        positions = [\n            p for p in range(history_length + tokens) if (p // 16) % shards == rank\n        ]\n        local_history = sum(p < history_length for p in positions)\n        pages = max(1, (len(positions) + 127) // 128)\n        stride = 128 * 576 + gap\n        storage = torch.full(\n            (offset + pages * stride + offset,), 0x5A, dtype=torch.uint8, device=device\n        )\n        cache = core.cache_view(storage[offset:-offset], pages, stride)\n        table = torch.arange(pages - 1, -1, -1, dtype=torch.int32, device=device)\n        pos = torch.arange(len(positions), device=device)\n        cache_slots = table[pos // 128].long() * 128 + pos % 128\n        if positions:\n            values = combined[torch.tensor(positions, device=device, dtype=torch.long)]\n            core.write_cache(values, cache_slots, cache, scale)\n            # Independent full backing-store oracle, including offsets and gaps.\n            expected = torch.full_like(storage.cpu(), 0x5A)\n            packed = (\n                values.cpu()\n                .float()\n                .clamp(-448, 448)\n                .to(torch.float8_e4m3fn)\n                .view(torch.uint8)\n            )\n            for i, slot in enumerate(cache_slots.cpu().tolist()):\n                page, row = divmod(slot, 128)\n                for tile in range(18):\n                    start = offset + page * stride + tile * 4096 + row * 32\n                    expected[start : start + 32] = packed[\n                        i, tile * 32 : (tile + 1) * 32\n                    ]\n            if not torch.equal(storage.cpu(), expected):\n                raise AssertionError("FP8 write bytes or guards mismatch")\n        before = storage.clone()\n        out = torch.empty(tokens, heads, 512, dtype=torch.bfloat16, device=device)\n        lse = torch.empty(tokens, heads, 1, device=device)\n        impl = SimpleNamespace(\n            dcp_enabled=shards > 1, dcp_rank=rank, qfm_scale=scale, scale=576**-0.5\n        )\n        batch = SimpleNamespace(fia_requests=((0, tokens, local_history, table),))\n        core.fill_fia_prefill(impl, q, current, cache, batch, out, lse)\n        torch.npu.synchronize()\n        if not torch.equal(before, storage):\n            raise AssertionError("FIA changed persistent FP8 cache")\n        result = (\n            (out, lse) if result is None else core.merge_fia_parts(result, (out, lse))\n        )\n    # Reader oracle uses actual Prolog BF16 outputs, isolating reader vs writer errors.\n    keys = torch.cat(\n        (history_cpu.to(torch.float8_e4m3fn).float(), current.cpu().float())\n    )\n    query = q.cpu().float()\n    scores = torch.einsum("thd,kd->thk", query, keys) * 576**-0.5\n    invalid = (\n        torch.arange(keys.shape[0])[None, :]\n        > (history_length + torch.arange(tokens))[:, None]\n    )\n    scores.masked_fill_(invalid[:, None], -float("inf"))\n    expected = torch.einsum("thk,kd->thd", scores.softmax(-1), keys[:, :512])\n    check(\n        torch,\n        "FIA_output_vs_actual_prolog_fp32_reference",\n        result[0],\n        expected,\n        atol=0.02,\n        rtol=0.02,\n        l2_limit=0.01,\n    )\n    check(\n        torch,\n        "FIA_LSE",\n        result[1][..., 0],\n        scores.logsumexp(-1),\n        atol=0.005,\n        rtol=0.001,\n        l2_limit=0.001,\n    )\n    emit(\n        "case_complete",\n        case=case,\n        passed=True,\n        prolog_mode=0,\n        persistent_cache="FP8",\n        current_scratch="BF16",\n        exhaustive_query_rows=tokens,\n        peak_allocated_mib=torch.npu.max_memory_allocated() / 1024**2,\n        scope="synthetic single-card eager; simulated DCP, not HCCL/model/performance acceptance",\n    )\n'}
"""Standalone FIA+Prolog test using the already validated private DSL runtime."""

import argparse
import hashlib
import json
import os
import subprocess
import sys
import tempfile
import types
from pathlib import Path

CASES = [
    (1, 0, 12, 0, 1),
    (9, 127, 12, 256, 2),
    (33, 129, 24, 0, 1),
    (33, 257, 24, 256, 2),
    (129, 127, 48, 0, 1),
    (129, 257, 48, 256, 2),
]
SOURCE_HASH = "ab0876c2fc09b7cc2b0541063dc7bab16414b2046ea9030bc1fecce4020be1bc"


def main():
    parser = argparse.ArgumentParser(
        description="FIA + mode0 DSL Prolog: no VA patch or installation"
    )
    parser.add_argument("--card", type=int, default=0)
    parser.add_argument(
        "--runtime", type=Path, default=Path("/mnt/k3-qfm-prolog-9e01355")
    )
    parser.add_argument("--timeout", type=int, default=1800)
    parser.add_argument("--plan", action="store_true")
    parser.add_argument("--worker", nargs=5, type=int)
    args = parser.parse_args()
    if args.plan:
        print(
            json.dumps(
                {
                    "cases": CASES,
                    "runtime": str(args.runtime),
                    "installs": False,
                    "qfm_needed": False,
                    "graph": False,
                    "may_jit_compile_mode0": True,
                }
            )
        )
        return 0
    prefix = args.runtime.resolve()
    receipt = json.loads((prefix / "receipt.json").read_text())
    source = prefix / "module/kimi_k3_quant_mla_prolog.py"
    if hashlib.sha256(source.read_bytes()).hexdigest() != SOURCE_HASH:
        raise RuntimeError("Private Prolog source differs from tested pin")
    runtime = Path(receipt["runtime_directory"]).resolve()
    if not runtime.is_relative_to(prefix) or not (runtime / "cannbotdsl").is_dir():
        raise RuntimeError("Private DSL runtime is incomplete or outside its prefix")
    if args.worker:
        sys.path[:0] = [str(prefix / "module"), str(runtime)]
        os.environ["ASCEND_RT_VISIBLE_DEVICES"] = str(args.card)
        os.environ.pop("ASCEND_DEVICE_ID", None)
        import importlib.metadata

        if importlib.metadata.version("cannbot-dsl") != "0.8.0":
            raise RuntimeError("Expected isolated DSL 0.8.0")
        modules = {}
        for name, code in PAYLOAD.items():  # noqa: F821 - supplied by bundle
            module = types.ModuleType(name)
            sys.modules[name] = module
            exec(compile(code, name + ".py", "exec"), module.__dict__)  # noqa: S102 - bundled local sources only
            modules[name] = module
        modules["fia_prolog_worker"].run(
            args.worker, modules["fia_core"], modules["prolog_reference"]
        )
        return 0
    directory = Path(tempfile.mkdtemp(prefix="fia-prolog-", dir="/mnt"))
    results = []
    for case in CASES:
        log = directory / f"case-{len(results)}.log"
        print(
            json.dumps(
                {
                    "event": "begin",
                    "case": case,
                    "log": str(log),
                    "note": "New mode/shape may compile; follow log for progress",
                }
            ),
            flush=True,
        )
        command = [
            sys.executable,
            "-u",
            str(Path(__file__).resolve()),
            "--card",
            str(args.card),
            "--runtime",
            str(prefix),
            "--worker",
            *map(str, case),
        ]
        timeout = False
        with log.open("w") as stream:
            process = subprocess.Popen(
                command, stdout=stream, stderr=subprocess.STDOUT, start_new_session=True
            )
            try:
                code = process.wait(timeout=args.timeout)
            except subprocess.TimeoutExpired:
                import signal

                os.killpg(process.pid, signal.SIGKILL)
                process.wait()
                code, timeout = -1, True
        records = []
        for line in log.read_text(errors="replace").splitlines():
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(record, dict):
                records.append(record)
        passed = code == 0 and any(
            r.get("event") == "case_complete" and r.get("passed") for r in records
        )
        result = {
            "case": case,
            "pass": passed,
            "returncode": code,
            "timeout": timeout,
            "log": str(log),
        }
        results.append(result)
        print(json.dumps({"event": "case_complete", **result}), flush=True)
        if not passed:
            print(
                "\n".join(log.read_text(errors="replace").splitlines()[-80:]),
                flush=True,
            )
            break
    success = len(results) == len(CASES) and all(r["pass"] for r in results)
    summary = {
        "all_passed": success,
        "completed": len(results),
        "planned": len(CASES),
        "results": results,
        "directory": str(directory),
        "scope": "mode0 Prolog + FP8 write + eager FIA; NOT real TP/DCP, graph or model acceptance",
    }
    (directory / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    print(json.dumps({"event": "summary", **summary}), flush=True)
    return 0 if success else 1


if __name__ == "__main__":
    raise SystemExit(main())
